:root {
  color-scheme: dark;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
  background: #172b35;
  color: #f5f0df;
}

* { box-sizing: border-box; }
body {
  min-width: 320px;
  min-height: 100vh;
  margin: 0;
  padding: 24px;
  display: grid;
  place-items: center;
  background: radial-gradient(ellipse at 50% 10%, #294957 0, #172b35 65%);
}
button { font: inherit; }
.board {
  width: min(100%, 680px);
  padding: clamp(24px, 6vw, 48px);
  border: 4px solid #426673;
  background: #203943;
  box-shadow: 8px 8px 0 #102027, 0 24px 70px #0c1a20aa;
}
.header { text-align: center; }
.eyebrow, .result-label {
  margin: 0;
  color: #d7a956;
  font-size: .8rem;
  font-weight: 800;
  letter-spacing: .14em;
  text-transform: uppercase;
}
h1 { margin: 8px 0; font-size: clamp(2rem, 7vw, 3.3rem); line-height: 1.08; }
.instructions { max-width: 430px; margin: 0 auto; color: #c4d1cc; line-height: 1.5; }
.game { margin-top: 34px; padding: 24px; border: 2px solid #426673; background: #192f38; }
.status-row { display: flex; justify-content: space-between; gap: 12px; color: #c4d1cc; font-size: .95rem; }
.round-status { color: #f5f0df; font-weight: 700; }
.dice { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 12px; margin: 28px 0 14px; }
.die {
  aspect-ratio: 1;
  min-width: 0;
  display: grid;
  place-items: center;
  border: 3px solid #d8d0b8;
  border-radius: 5px;
  background: #f5f0df;
  color: #203943;
  box-shadow: 4px 4px 0 #102027;
  cursor: pointer;
  font-size: clamp(2rem, 9vw, 3.6rem);
  font-weight: 900;
  line-height: 1;
  transition: transform 120ms ease, background 120ms ease, border-color 120ms ease;
}
.die:hover { transform: translateY(-3px); }
.die:active { transform: translateY(2px); box-shadow: 1px 1px 0 #102027; }
.die[aria-pressed="true"] { border-color: #d7a956; background: #d7a956; transform: translateY(-5px); }
.die:focus-visible, .button:focus-visible { outline: 3px solid #fff; outline-offset: 4px; }
.hold-hint { margin: 0; text-align: center; color: #9eb3b2; font-size: .9rem; }
.actions { display: flex; flex-wrap: wrap; justify-content: center; gap: 12px; margin-top: 24px; }
.button { min-height: 50px; padding: 10px 20px; border: 2px solid transparent; border-radius: 3px; cursor: pointer; font-weight: 800; transition: transform 120ms ease, filter 120ms ease; }
.button:hover { filter: brightness(1.12); transform: translateY(-2px); }
.button:active { transform: translateY(2px); }
.button:disabled { cursor: not-allowed; filter: grayscale(.6); opacity: .55; transform: none; }
.button-primary { background: #d7a956; color: #172b35; }
.button-secondary { border-color: #789398; background: transparent; color: #f5f0df; }
.result { display: grid; justify-items: center; gap: 7px; margin-top: 26px; padding-top: 20px; border-top: 1px solid #426673; text-align: center; }
.result strong { color: #f5f0df; font-size: clamp(1.5rem, 5vw, 2rem); }
footer { margin-top: 22px; color: #9eb3b2; font-size: .85rem; text-align: center; }
@media (max-width: 420px) {
  body { padding: 14px; }
  .board { padding: 22px 16px; }
  .game { padding: 18px 12px; }
  .dice { gap: 8px; }
  .die { border-width: 2px; box-shadow: 3px 3px 0 #102027; }
  .status-row { font-size: .85rem; }
}

const diceContainer = document.querySelector('#dice');
const rollButton = document.querySelector('#roll-button');
const newRoundButton = document.querySelector('#new-round-button');
const rollCountLabel = document.querySelector('#roll-count');
const roundStatus = document.querySelector('#round-status');
const handName = document.querySelector('#hand-name');
const faceNames = ['', 'one', 'two', 'three', 'four', 'five', 'six'];

let values = [];
let held = [];
let rerolls = 0;
let finished = false;

function handFor(dice) {
  const counts = Array(7).fill(0);
  dice.forEach(value => counts[value]++);
  const groups = counts.filter(count => count > 0).sort((a, b) => b - a);
  const unique = [...new Set(dice)].sort((a, b) => a - b);
  const straight = unique.length === 5 && unique.every((value, i) => i === 0 || value === unique[i - 1] + 1);

  if (groups[0] === 5) return 'Five of a kind';
  if (groups[0] === 4) return 'Four of a kind';
  if (groups[0] === 3 && groups[1] === 2) return 'Full house';
  if (straight) return 'Straight';
  if (groups[0] === 3) return 'Three of a kind';
  if (groups[0] === 2 && groups[1] === 2) return 'Two pair';
  if (groups[0] === 2) return 'Pair';
  return 'High die';
}

function renderDice() {
  diceContainer.replaceChildren();
  values.forEach((value, index) => {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'die';
    button.textContent = String(value);
    button.setAttribute('aria-label', `Die ${index + 1}: ${faceNames[value]}${held[index] ? ', held' : ', not held'}`);
    button.setAttribute('aria-pressed', String(held[index]));
    button.disabled = finished;
    button.addEventListener('click', () => {
      held[index] = !held[index];
      renderDice();
    });
    diceContainer.append(button);
  });
}

function updateStatus() {
  rollCountLabel.textContent = `Rerolls: ${rerolls} / 2`;
  rollButton.disabled = finished || rerolls >= 2;
  rollButton.textContent = rerolls === 0 ? 'Roll dice' : 'Reroll unheld';
}

function roll() {
  if (finished) return;
  values = values.map((value, index) => held[index] ? value : Math.floor(Math.random() * 6) + 1);
  rerolls++;
  renderDice();
  updateStatus();
  if (rerolls === 1) {
    roundStatus.textContent = 'Choose holds, then reroll';
  } else {
    finished = true;
    handName.textContent = handFor(values);
    roundStatus.textContent = 'Round complete';
    renderDice();
    updateStatus();
  }
}

function newRound() {
  values = Array.from({ length: 5 }, () => Math.floor(Math.random() * 6) + 1);
  held = Array(5).fill(false);
  rerolls = 0;
  finished = false;
  handName.textContent = 'Choose your holds';
  roundStatus.textContent = 'Your opening roll';
  renderDice();
  updateStatus();
}

rollButton.addEventListener('click', roll);
newRoundButton.addEventListener('click', newRound);
newRound();
